@startuml

enum LevelOfTutoring {
  PrimarySchool
  HighSchool
  University
}

enum SessionStatus {
  Proposed
  Confirmed
  Completed
  Paid
  Cancelled
}

enum PaymentKind {
  CreditCard
  WireTransfer
}

class User {
  + name : string
  + email : string
}

class BestTutorAward {
  + month : int
}

class Tutor extends TutoringRole {
  + bankAccount : string
}

class TutoringOffer extends TutoringElement {
  + hourlyPrice : float
}

class Subject {
  + name : string
}

class TutorAvailability {
  + dayOfWeek : string
  + startTime : time
  + endTime : time
}

abstract class TutoringRole {}

abstract class TutoringElement {
  + tutoringLevel : LevelOfTutoring
}

class Student extends TutoringRole {}

class TutoringRequest extends TutoringElement {
  + targetDate : date
  + targetTime : time
}

class TutoringSession {
  + sessionDate : date
  + sessionTime : time
  + sessionStatus : SessionStatus
}

class Payment {
  + paymentForm : PaymentKind
}

User "1" -- "0..2" TutoringRole
Tutor "1" *-- "*" TutoringOffer
Tutor "1" *-- "*" TutorAvailability
Tutor "1" -- "*" BestTutorAward
Student "1" *-- "*" TutoringRequest
TutoringRequest "1" -- "1" TutoringSession
TutoringSession "1" -- "1" Student : student
TutoringSession "1" -- "1" Tutor : tutor
TutoringSession "1" -- "0..1" Payment
TutoringRequest "1" -- "1" Tutor : designated tutor
Subject "1" -- "*" TutoringOffer
Subject "1" -- "*" TutoringRequest
TutoringOffer "0..1" -- "*" TutoringRequest
TutoringSession "1" --> "0..1" TutoringSession : follow-up

@enduml

